describe('edge', () => {
  test('verse 1 is single line', () => {
    expect(House.verse(1)).toEqual(['This is the house that Jack built.']);
  });
  test('verses(1,1) has no blank separators', () => {
    expect(House.verses(1, 1)).toEqual(['This is the house that Jack built.']);
  });
  test('verses(12,12) matches verse(12)', () => {
    expect(House.verses(12, 12)).toEqual(House.verse(12));
  });
  test('verses(2,3) separator and content', () => {
    expect(House.verses(2, 3)).toEqual([
      'This is the malt',
      'that lay in the house that Jack built.',
      '',
      'This is the rat',
      'that ate the malt',
      'that lay in the house that Jack built.',
    ]);
  });
  test('verse lengths grow by one', () => {
    for (let v = 1; v <= 12; v += 1) expect(House.verse(v)).toHaveLength(v);
  });
  test('out of range throws', () => {
    expect(() => House.verse(0)).toThrow(RangeError);
    expect(() => House.verse(13)).toThrow(RangeError);
    expect(() => House.verse(1.5)).toThrow(RangeError);
  });
});
